        [415320] = "Ви та ваш вихованець одночасно миттєво завдаєте $s2% шкоди ближнього бою. Після цього ви завдаєте на $s3% більше шкоди протягом $d, ефект накопичується до $u разів. Основні атаки вашого вихованця мають $s4% шанс скинути час відновлення «Флангового удару».",
        [415358] = "«Удар раптора» збільшує шкоду від «Удару раптора» та «Укусу мангуста» на $415362s2% протягом $415362d, накопичуючись до $415362u разів. Наступні накладання не подовжують тривалість ефекту.",
        [415399] = "Якщо ви не рухалися протягом останньої 1 с, маєте $m1% шанс отримати «Снайперський приціл», що накопичується до $415401u разів. «Снайперський приціл» збільшує ймовірність критичного удару ваших здібностей пострілу на $415401s1%.",
        [415405] = "Зменшує час відновлення «Швидкої стрільби» на ${$m1/-60000} хв. Крім того, коли ви вбиваєте нетривіального ворога або він помирає під дією вашого «Зміїного жала», ви отримуєте «Швидке вбивство», що збільшує шкоду вашої наступної здібності пострілу протягом $415407d на $m2%.",
        [415596] = "Ви отримуєте здібність «Майстерність щита»:\r\n\r\n$@spellicon409069\r\n$@spelldesc409069",
        [415739] = "«Мале зцілення», «Зцілення», «Велике зцілення» та «Швидке зцілення» зменшують тривалість «Ослабленої душі» на зцілених цілях на $409317s1 с. Крім того, цілі вашого «Слова сили: Щит» отримують лють від шкоди, навіть якщо її поглинуто, а «Праведна лють» спрацьовує від шкоди, поглинутої вашим «Словом сили: Щит», наче від зцілення.",
        [415813] = "Вашу здібність «Примарний вовк» тепер можна використовувати в приміщенні, а під час її дії вся отримувана шкода зменшується на $415233s3%.",
        [416084] = "Вигравіюйте на поясі руну «Аспект гадюки»:\r\n\r\n$@spellicon415423\r\nМисливець переймає аспекти гадюки, через що атаки дальнього та ближнього бою відновлюють ману, але шкода зменшується на $s2%. Крім того, ви відновлюєте $s1% від максимального запасу мани кожні $t секунди. Кількість отриманої мани залежить від швидкості вашої зброї. Одночасно може бути активним лише один аспект.",
        [416087] = "Вигравіюйте на поясі руну «Смертельний постріл»:\r\n\r\n$@spellicon409593\r\nВи намагаєтеся добити поранену ціль точним пострілом, завдаючи їй $s2% шкоди від зброї плюс ${$m1/100*$m2/100*$<damagepower>}. \"Вбивчий постріл\" не має мінімальної дальності застосування. При застосуванні проти ворогів, що мають не більше 20% здоров'я, його відновленя завершується.",
        [416772] = "Покладіть як приманку біля лігва острівної кішки",
        [417045] = "Миттєво надає вам енергію.",
        [417046] = "«Лють тигра» тепер миттєво надає вам $s1 енергії.",
        [417051] = "Збільшує вашу ймовірність ухилення на $m1% і дає $m2% шанс отримати ${$417053m1/10} люті щоразу, коли ви ухиляєтеся.",
        [417141] = "$?a5487|a9634|a3025[|CFFFFFFFFReuires Cat Form, Bear Form, Dire Bear Form|R][|CFFFF2020Requires Cat Form, Bear Form, Dire Bear Form|R]\r\nВаша здібність «Первісний укус» уражає до $s3 цілей, більше не має часу відновлення та збільшує ймовірність критичного удару здібностей, що дають очки серії, на $s1%. Знімає ефекти страху та надає несприйнятливість до них на час дії. Триває $d.",
        [417147] = "Зцілює всіх учасників групи або рейду в межах $417148a1 ярдів від вибраної області на ${$<healpower>*$417148m1/100} кожні $417147t1 с протягом $d.",
        [417149] = "Ваше «Швидке відновлення» тепер також спричиняє «Цвітіння», що зцілює всіх учасників групи в межах $417148a1 ярдів від місця цілі «Швидкого відновлення» на ${$<healpower>*$417148m1/100} кожні $417147t2 с протягом $417147d.",
        [417157] = "Вивільняє потужну зоряну енергію, що завдає від ${$m1/100*$<damagepower>} до ${$M1/100*$<damagepower>} шкоди від таємної магії та збільшує шкоду ваших наступних $n $Lcast:casts; «Зоряного вогню» на $s2% протягом $d.\r\n\r\n«Зоряний сплеск» отримує переваги від більшості талантів і ефектів, що спрацьовують від «Гніву» або «Зоряного вогню» чи посилюють їх.",
        [417453] = "Надає кілька нових демонічних здібностей: «Зрив», «Демонічний ривок», «Демонічне виття» та «Пекельний удар».\r\n\r\n$@spellicon412787\r\nДушить ворога сплеском тіньової енергії, завдаючи $s1 шкоди, перериваючи вимовляння закляття та не даючи застосовувати закляття цієї школи протягом $d.\r\n\r\n$@spellicon412788\r\nЗдійснює ривок до ворога й приголомшує його на $7922d.  Не можна використовувати в бою.\r\n\r\n$@spellicon412789\r\nЗмушує всіх ворогів поблизу зосередити атаки на вас протягом $d.\r\n\r\n$@spellicon412790\r\nСтрибає в повітря й обрушується на всіх ворогів у межах $a2 ярдів від вибраної області, завдаючи $s2 шкоди від тіні та приголомшуючи їх на $d.",
        [417743] = "Створіть підроблені документи, що звинувачують Багряний похід у діях проти Альянсу.  Потрібне письмове приладдя з ратуші Брілла.",
        [418347] = "Поєднайте 6 нотаток аптекаря, щоб створити новий рецепт гравіювання.",
        [418489] = "Покладіть як приманку всередині барлогу великого ведмедя",
        [418506] = "Завдає ворогові фізичної шкоди кожні $t1 с протягом $d.",
        [418508] = "Ваша наступна атака гарантовано буде критичною.",
        [418509] = "Після завдання смертельного удару, що дає досвід або честь, ваша наступна атака гарантовано буде критичною.",
        [418510] = "Трохи збільшує шкоду та силу зцілення вашої групи.",
        [418738] = "-15 до опору вогню",
        [419126] = "Показує, скільки трофеїв ви здобули за перемоги в дуелях до смерті.",
        [420535] = "Намагається вкрасти предмети в цілі.",
        [420684] = "Створює магічний спис блискавки та жбурляє його у ворога.",
        [420710] = "Ошалілий.",
        [420843] = "Телепортує заклинача на 20 ярдів назад, якщо ніщо не заважає. Також звільняє заклинача від будь-яких пут.",
        [420964] = "Жбурнути гарпун у ціль (дальність 40 ярдів)",
        [421197] = "Киньте в колодязь поблизу, щоб загадати бажання",
        [421295] = "Покладіть як приманку всередині барлогу великого ведмедя",
        [421406] = "Викличте таурена на дуель",
        [421436] = "Поєднайте 3 квітки галявини, щоб зробити вінок.",
        [421599] = "Згодуйте цілі приманку.",
        [422171] = "Згодуйте цілі ласощі.",
        [422387] = "Посадити гарбузове насіння",
        [422397] = "Жбурнути гарпун у ціль (дальність 40 ярдів)",
        [422477] = "Поєднайте запасні деталі женця зі стихійним ядром, щоб створити прототип двигуна.",
        [422478] = "Установіть у прототип збирального женця.",
        [422488] = "Покладіть як приманку біля лігва койота",
        [422498] = "Женіться за згасаючим світлом!",
        [422996] = "Обливає ціль стародавньою їдкою отрутою, що завдає $m1 шкоди від сил природи кожні 3 с і зменшує броню цілі на $m2 протягом $d.",
        [423003] = "Вивільняє іскру грому, завдаючи $s1 шкоди від сил природи.",
        [423004] = "Вивільняє порив вітру, завдаючи $s1 шкоди від сил природи.",
        [423088] = "Відкрити промоклу скриню капітана",
        [423187] = "Урівноважте сили Місяця, Смарагдового Сну та Дикої природи, щоб вивчити нову здібність.",
        [423253] = "Завдає великої шкоди поблизу; якщо ворогів не вражено, завдає шкоди самому заклиначеві.",
        [423299] = "Збільшує шкоду фізичних атак проти звірів на $s1. ",
        [423300] = "М’ґррґл супроводжуватиме вас протягом $d1, надаючи невеликий захист від тіні.",
        [423304] = "Висмоктує життя з жертви, зцілюючи вас на $s1 шкоди.",
        [423481] = "Трохи покращує виявлення непомітності.",
        [423484] = "Збільшує шкоду ваших вихованців на $s1%.",
        [423549] = "Наповніть великий магічний жезл дикою магією.",
        [423632] = "Відкрити промоклу скриню капітана.",
        [424573] = "Поранений, отримує періодичну шкоду та інші виснажливі ефекти.",
        [424574] = "Виснажений.",
        [424645] = "Перекладіть нотатки закляття в новий рецепт рунорізьблення.  Потрібен довідник скорочень автора.",
        [424788] = "Розберіть уламки подрібнювача на запасні частини.",
        [424919] = "Миттєво завдає удару зброєю в другій руці зі звичайною шкодою цієї зброї та збільшує ймовірність парирування на $s2% протягом $d або до успішного парирування. Протягом $462752d після використання «Мен-гоша» «Підступний удар» коштує на $462752s1 менше енергії, створює на $462752s2% більше загрози, надає заряди «Тримати удар», а «Підступний удар» і «Потрошіння» завдають на $462752s3% більше шкоди. Дає $s3 $lpoint:points; серії.\r\n\r\n«Мен-гош» отримує переваги від більшості талантів та ефектів, що спрацьовують від «Підступного удару» або змінюють його. Ефект «Мен-гоша» не здешевлює й не посилює сам «Мен-гош».",
        [424925] = "Зменшує витрати енергії на «Удар у спину» та «Засідку» на $s1 і збільшує їхню шкоду по цілях, не керованих гравцями, на $s2%. $?s400094[Does not apply to Mutilate.][Does not apply to abilities learned from other runes.]",
        [425067] = "Відкрити важку браму — по-гоблінськи!",
        [425094] = "Поєднайте половинки ключа Брата й Сестри.",
        [425121] = "Прискорює вимовляння заклять, збільшуючи швидкість їх застосування на $s1% і зменшуючи затримку від отриманої шкоди під час вимовляння на $s2%. Триває $d.",
        [425124] = "Вивільняє всю вашу решту мани сплеском енергії, спрямованим у ціль, завдаючи від ${$<power>*$m1/100} до ${$<power>*$M1/100} шкоди від таємної магії, збільшеної до $s4% залежно від залишку мани. Після цього ваше звичайне відновлення мани відновлюється та збільшується на $s2% протягом $d.",
        [425204] = "Уражає ціль хворобою, що завдає ${$<damagepower>*$m1/100*6} шкоди від тіні протягом $d.",
        [425226] = "Горить!",
        [425280] = "Ваші зцілення від «Швидкого зцілення», «Спільного зцілення», «Малого зцілення», «Зцілення», «Великого зцілення» та «Спокути» мають на $m1% більшу ймовірність критичного ефекту по цілях з «Ослабленою душею» та зменшують залишок тривалості «Ослабленої душі» на цілі на ${$m2/-1000} с.",
        [425284] = "Активуйте, щоб стати «Духом спокути» на $d. У цій формі ви можете безкоштовно застосовувати будь-які закляття зцілення, але не можете рухатися, атакувати, бути атакованим чи ставати ціллю заклять або ефектів. Для активації потрібен талант «Дух спокути», і після смерті ви більше не переходитимете у форму «Духа спокути».",
        [425285] = "Закликає духів стихій.",
        [425294] = "Ви розчиняєтеся в чистій енергії тіні, зменшуючи всю отримувану шкоду на $s1%.  Ви не можете атакувати чи застосовувати закляття, але відновлюєте $s2% мани кожні $t2 с протягом $d. «Розсіювання» можна застосовувати під час приголомшення, страху або мовчанки; воно знімає всі ефекти сповільнення й обмеження руху та робить вас несприйнятливим до них на час дії.",
        [425418] = "Вводить вас у стан люті (активуючи здібності, що потребують цього стану) на $425415d після того, як ваша лють перевищить $s1. Крім того, під час люті «Вихор» також завдає ударів зброєю в другій руці.",
        [425463] = "Вас переповнює енергія Скверни, збільшуючи ймовірність ухилення вас і вашого вихованця на $s1%, а вашу ймовірність критичного удару всіма атаками — на $s2%. Триває $d.",
        [425464] = "Ефект вашої «Демонічної жертви» більше не скасовується прикликанням іншого демона. Повторне прикликання принесеного в жертву демона все ще скасовує ефект.\r\n",
        [425497] = "Кинути приманку.",
        [425600] = "Паладин сурмить у Ріг Лордерона, збільшуючи загальну силу та спритність усіх учасників групи в межах $a1 ярдів на $?s25291[89][${$cond($gte($PL,56),74,$cond($gte($PL,52),60,$cond($gte($PL,42),45,$cond($gte($PL,32),26,$cond($gte($PL,22),17,$cond($gte($PL,12),11,6)))))))}]. Триває $d. Несумісне з «Благословенням могутності».",
        [425609] = "Перериває вимовляння закляття й не дає застосовувати закляття цієї школи протягом $d.",
        [425738] = "Цілі, уражені вашим «Мультипострілом», також отримують «Зміїне жало» на $425728d.",
        [425894] = "Завдає ворогові фізичної шкоди кожні $t1 с протягом $d.",
        [426019] = "З’їсти (на власний ризик).",
        [426065] = "Критичні ефекти ваших «Святого шоку» та «Спалаху Світла» зменшують час вимовляння наступного «Святого Світла» протягом $437063d на ${$m1/-1000}.1 с.",
        [426157] = "Збільшує всю завдану вами шкоду від святості на $m1%, а ваші критичні удари ближнього бою та закляттями зменшують залишок часу відновлення «Екзорцизму» на ${$m2/-1000} с.",
        [426162] = "\r\n\r\n",
        [426195] = "Після активації тимчасово збільшує ваш максимальний запас здоров’я на $s1% протягом $d. Після завершення ефекту додаткове здоров’я втрачається. Крім того, у «Метаморфозі» «Помста» змушує ваші крила сповільнювати падіння.",
        [426301] = "Шкода, завдана вами або вашим прикликаним демоном, має $h% шанс збільшити шкоду іншого на $426303s1% протягом $426303d.",
        [426311] = "Збільшує всю завдану шкоду від вогню на $s1%.",
        [426316] = "Удар «Спалахом вогню» збільшує всю вашу шкоду від тіні на $m3% протягом $1293816d, а удар «Опіком тіні» збільшує всю вашу шкоду від вогню на $m4% протягом $426311d. Крім того, «Спалах вогню» має $m2% шанс не поглинути «Жертовний вогонь», а «Опік тіні» — $m2% шанс миттєво повернути уламок душі.",
        [426320] = "Обпалює ворога на ${$m1*$<power>/100*$<mult>} шкоди тіньовим полум’ям, а потім завдає ще ${$m2*5*$<power>/100} шкоди тіньовим полум’ям протягом $d.\r\n\r\n«Тіньове полум’я» спрацьовує від усіх ефектів, що змінюють «Жертовний вогонь» або взаємодіють із ним, а також із закляттями Недуг, Руйнування, Вогню чи Тіні, і отримує від них переваги. Однак на одній цілі від одного чорнокнижника може діяти лише один із ефектів «Жертовний вогонь» або «Тіньове полум’я». Крім того, «Тіньове полум’я» може активувати талант «Покращена тіньова стріла» та надає йому $426454s2 додаткові заряди.",
        [426490] = "Видає згуртовуючий клич, збільшуючи максимальний запас здоров’я всіх учасників групи й рейду в межах $a1 ярдів на $s1% протягом $d.",
        [426597] = "..",
        [426612] = "Побачте видіння біля вогнища Дже’неу.",
        [426633] = "Зробіть криваву жертву та звільніть душу всередині.",
        [426694] = "Перетворює на ведмедя на $d, збільшуючи броню та запас здоров’я й дозволяючи використовувати різні ведмежі здібності.",
        [426754] = "Зробіть криваву жертву, щоб звільнити цю Змучену душу.",
        [426940] = "Впадає в шаленство, збільшуючи силу атаки на $s1% протягом $d.  Цю здібність можна використовувати лише в стані люті.",
        [426953] = "Щоразу, коли «Роздирання» завдає шкоди, «Перевага» активується на $426969d або на 1 атаку.  Ефект не може виникати частіше ніж раз на $s1 с.",
        [426972] = "Зосереджує захисний погляд на учаснику групи або рейду, зменшуючи отримувану ним шкоду на $s1% і передаючи вам $m2% створюваної ним загрози.  Крім того, щоразу, коли його атакують, час відновлення вашої «Провокації» скидається.  Триває $d.  Ефект може діяти лише на одну ціль одночасно.",
        [426978] = "Коли ваші «Спустошення» та «Помста» завдають шкоди, вони мають $h% шанс скинути час відновлення «Удару щитом» і зменшити його витрати люті на $426979s1% протягом $426979d.",
        [426980] = "Поки у вас екіпірований щит, уся ваша фізична шкода збільшується на $426981s1%, а тривалість усіх ефектів роззброєння проти вас зменшується на $s2%.  Не сумується з іншими ефектами, що зменшують тривалість роззброєння.\r\n",
        [426981] = "\r\n\r\n",
        [427020] = "Додайте $q2 мідних зливків, щоб завершити вантаж.",
        [427065] = "Ваші критичні удари ближнього бою вводять вас у стан люті (активуючи здібності, що його потребують) і збільшують шкоду «Смертельного удару», «Кровожерливості» та «Удару щитом» на $427066s1% протягом $427066d.",
        [427143] = "Збільшує всю шкоду, отримувану ворогом, на $s1 протягом $d.",
        [427144] = "Цей предмет наповнений первісною силою Порожнечі. Коли власника атакують, предмет має високу ймовірність накласти жахливе прокляття, через яке нападник протягом 15 секунд отримує додаткову шкоду з усіх джерел. \r\n",
        [427592] = "Маскує вас під члена Багряного походу. Підозріла діяльність знімає маскування.",
        [427713] = "«Спалах вогню» також надає $427714s1% швидкості вимовляння заклять на $427714d і більше не поглинає «Жертовний вогонь».",
        [427717] = "Енергія тіні повільно руйнує ціль, завдаючи $o1 шкоди протягом $d. Крім того, якщо «Нестабільну недугу» розвіють, вона завдасть розвіювачу ${$m1*$m3/100} шкоди та накладе мовчанку на $427719d. На одній цілі від одного чорнокнижника може діяти лише одна «Нестабільна недуга» або «Жертовний вогонь».",
        [427745] = "Здійснює ривок до ворога, завдаючи $427746s2 шкоди та приголомшуючи його на $427746d.",
        [428489] = "На мить переходить в інший план буття, миттєво зменшуючи загрозу, а також усю отримувану й завдану шкоду на $M% протягом $d. ",
        [428490] = "«Правосуддя» створює додатково $s1% загрози проти своєї цілі. ",
        [428491] = "Ваша «Аура відданості» також зменшує всю отримувану шкоду від заклять на $s1%. ",
        [428567] = "Спіймайте дрібну тварину, щоб використати її як приманку.",
        [428604] = "Покладіть дрібну тварину як приманку.",
        [428708] = "Щосекунди протягом $d перетворює ресурси на здоров’я. Щосекунди до $s1 люті, $s2 енергії або $s3% базової мани перетворюється на до $s4% здоров’я.",
        [428713] = "Шкіра цілі стає міцною, наче кора. Отримувана фізична шкода зменшується на $s2%.  Під захистом атаки, що завдають шкоди, не затримують вимовляння заклять. Триває $d.",
        [428726] = "Поглинає всі накладання «Шаленства» вашого вихованця, збільшуючи швидкість ваших дальніх атак на $s1% і надаючи вихованцю $s2 концентрації за кожне поглинуте накладання. Триває $d.\r\n\r\nВаш вихованець отримує «Шаленство» щоразу, коли використовує основну атаку, збільшуючи швидкість своїх атак ближнього бою на $428728s1% протягом $428728d; ефект накопичується до $428728u разів.",
        [428728] = "Збільшує швидкість атак ближнього бою вашого вихованця на $s1% протягом $d.",
        [428739] = "Приголомшує ціль на $d.  Можна використовувати лише на заморожених цілях.  Цілям із постійною несприйнятливістю до приголомшення завдає від ${$428917m1*$<power>/100*$<frostdamage>} до ${$428917M1*$<power>/100*$<frostdamage>} шкоди. Ця шкода отримує переваги від зарядів «Зледеніння», але не поглинає їх.",
        [428741] = "Коли вас атакують, завдає ${$428743m1/100*$<power>} шкоди від вогню, збільшує ймовірність критичного удару закляттями на $s3% і зменшує ймовірність отримати критичний удар на $s2%.  Одночасно на магові може діяти лише одне закляття типу «Броня».  Триває $d.",
        [428837] = "Додайте $q2 легкої шкіри, щоб завершити вантаж.",
        [428838] = "Додайте $q2 мироцвіту, щоб завершити вантаж.",
        [428840] = "Додайте $q2 срібнолисту, щоб завершити вантаж.",
        [428842] = "Додайте $q2 малих зіль зцілення, щоб завершити вантаж.",
        [428843] = "Додайте $q2 мідних коротких мечів, щоб завершити вантаж.",
        [428844] = "Додайте $q2 рунічних мідних штанів, щоб завершити вантаж.",
        [428845] = "Додайте $q2 малих магічних жезлів, щоб завершити вантаж.",
        [428846] = "Додайте $q2 малого чарівницького мастила, щоб завершити вантаж.",
        [428847] = "Додайте $q2 грубих мідних бомб, щоб завершити вантаж.",
        [428848] = "Додайте $q2 грубих громових рушниць, щоб завершити вантаж.",
        [428849] = "Додайте $q2 вручну зшитих шкіряних поясів, щоб завершити вантаж.",
        [428850] = "Додайте $q2 тиснених шкіряних жилетів, щоб завершити вантаж.",
        [428851] = "Додайте $q2 коричневих лляних штанів, щоб завершити вантаж.",
        [428853] = "Додайте $q2 коричневих лляних мантій, щоб завершити вантаж.",
        [428855] = "Додайте $q2 яєць, запечених із травами, щоб завершити вантаж.",
        [428856] = "Додайте $q2 пряного вовчого м’яса, щоб завершити вантаж.",
        [428857] = "Додайте $q2 блискучих дрібних рибок, щоб завершити вантаж.",
        [428858] = "Додайте $q2 щільних лляних бинтів, щоб завершити вантаж.",
        [428878] = "Вивільняє у ворога викривлювальний реальність сплеск первісної магії, завдаючи від ${$<power>*$m1/100} до ${$<power>*$M1/100} химерної шкоди.\r\n\r\nЗбільшує шкоду ваших «Стріли згубного вогню» та «Вогняної брили» на $s3%, зменшує дух на $s2% і накопичується до $u разів протягом $d. Якщо ваш дух досягне 0, ви помрете.\r\n\r\nЦе закляття перевіряється проти найнижчого з опорів цілі до таємної магії, вогню й криги.",
        [428885] = "Запускає сферу часової енергії, що повільно рухається вперед і кожні $428888t1 с надає всім учасникам групи поблизу щит, який поглинає ${$428895m1*$<power>/100} шкоди протягом $428895d. Цей щит накопичує додаткове поглинання, якщо учасники групи залишаються біля сфери.",
        [428909] = "Ваше «Святе Світло» зменшує час вимовляння наступного «Святого Світла» на ${$428912m1/-1000}.1 с. Триває $428912d.",
        [428912] = "\r\n\r\n",
        [429125] = "Прискорює вимовляння заклять, збільшуючи швидкість їх застосування на $s1% і зменшуючи затримку від отриманої шкоди під час вимовляння на $s2%.  Триває $d.",
        [429142] = "Збільшує ймовірність критичного удару закляттями на $s1%. Крім того, ваші критичні зцілення зцілюють ціль ще на $s2% від зціленої кількості протягом $426162d.",
        [429144] = "Зменшує витрати мани на «Очищення» та «Очищення від скверни» на $m1% і час відновлення «Екзорцизму» та «Святого гніву» на $m2%.",
        [429145] = "Випускає стріли святої сили в усі боки, завдаючи $s1 шкоди від святості всім цілям у межах $a1 ярдів і приголомшуючи демонів та невмерлих на $429147d.",
        [429146] = "Випускає стріли святої сили в усі боки, завдаючи $s1 шкоди від святості всім цілям у межах $a1 ярдів і приголомшуючи демонів та невмерлих на $429147d.",
        [429339] = "Захищає власника від ефектів «Нищівної темряви».",
        [429347] = "Спробуйте використати потужне джерело Світла, щоб знищити Скриньку.",
        [429350] = "Спробуйте протиставити Порожнечі Світло й знищити Скриньку.",
        [429732] = "Кладе на землю перед вами бомбу з коротким ґнотом.",
        [429838] = "Завдає цілі $s1 шкоди від вогню.",
        [429864] = "Збільшує вашу силу на $s. ",
        [429865] = "Поки діє «Нерозважливість», ваше «Стратити» завдає шкоди так, ніби у вас на 5 люті більше. ",
        [429867] = "Поринаєте в божевілля, збільшуючи швидкість атаки на $M% і створювану загрозу протягом $d. ",
        [429868] = "Поринаєте в божевілля, збільшуючи шкоду заклять на $M% і створювану загрозу протягом $d. ",
        [429959] = "Отримуваний досвід збільшено на $429959s0%. ",
        [429961] = "Розгортає спальний мішок. Відпочинок у ньому щонайменше одну хвилину надає бонус до отримуваного досвіду, що накопичується до 3 разів.",
        [429972] = "Поміркуйте біля певної відлюдної могили в Смерколіссі, щоб отримати пророцтво.",
        [430021] = "Поміркуйте біля ловця снів Будяколапих високо в кронах, щоб отримати пророцтво.",
        [430236] = "Розшифруйте сувій. Хто знає, яка магія в ньому міститься?",
        [430352] = "Збільшує всю завдану шкоду та зцілення на $s1% протягом $d.",
        [430374] = "Додайте $q2 бронзових зливків, щоб завершити вантаж.",
