        [430391] = "Зачароване лезо збільшує вашу ймовірність влучання на $s1%. Не діє поза Чорними глибинами.",
        [430392] = "Після нанесення на вибрану зброю збільшує ймовірність влучання на 2% протягом 30 хвилин. Не діє поза Чорними глибинами.",
