        [430403] = "Додайте $q2 копченого ведмежого м’яса, щоб завершити вантаж.",
        [430404] = "Додайте $q2 гострих молюсків по-ґоблінськи, щоб завершити вантаж.",
        [430405] = "Додайте $q2 щільних вовняних бинтів, щоб завершити вантаж.",
        [430406] = "Відновлює $s1 мани кожні $t1 с і збільшує ймовірність влучання закляттями на 2%. Цей ефект діє лише в Чорних глибинах.",
        [430409] = "Створює мастило мани Чорних глибин.",
        [430419] = "Розшифруйте сувій за допомогою оберега розуміння. Хто знає, яка магія в ньому міститься?",
        [430432] = "Зменшує всю отримувану шкоду та ймовірність отримати критичний удар на $s1% в Ущелині Пісні Війни.",
        [430472] = "\r\n\r\n",
        [430491] = "Невдача! Ваш загальний запас здоров’я зменшено на 10% на 20 хвилин.",
