        [430499] = "О ні! Вас знову понижено до новачка!",
        [430501] = "Ви почуваєтеся нестійко! ",
        [430585] = "Після нанесення на вибрану зброю відновлює 12 мани кожні 5 с і збільшує ймовірність влучання закляттями на 2% протягом $t1 хвилин. Цей ефект діє лише в Чорних глибинах.\r\n",
        [430771] = "Додайте $q2 грубого каменю, щоб завершити вантаж.",
        [430773] = "Додайте $q2 зіль зцілення, щоб завершити вантаж.",
        [430776] = "Додайте $q2 еліксирів сили вогню, щоб завершити вантаж.",
        [430950] = "Збільшує ваш опір вогню на $s1 протягом $d1. ",
        [430951] = "Збільшує ваш опір кризі на $s1 протягом $d1. ",
        [431389] = "Ваше «Шалене відновлення» тепер можна використовувати в усіх формах, крім форми місячного совозвіра, а також не у формі перевтілення. Тепер воно щосекунди протягом $428708d перетворює ваш активний ресурс на здоров’я. Щосекунди до $428708s1 люті, $428708s2 енергії або $428708s3% базової мани перетворюється на до $428708s4% здоров’я.\r\n",
        [431606] = "Збільшує швидкість атак ближнього бою вихованця на $s1% протягом $d.",
        [431622] = "Ваші критичні зцілення створюють на цілі захисний щит, що поглинає $s1% від зціленої кількості. Триває $431624d.",
        [431624] = "Критичні зцілення мають шанс створити на цілі захисний щит, що поглинає частину зціленої кількості. Триває $d.\r\n",
        [431664] = "Критичні застосування заклять роблять ваше наступне «Кара» або «Швидке зцілення» протягом $431666d миттєвим.",
        [431681] = "Прикликає в цільовій області зону Порожнечі, що завдає ${$<damagepower>*$431690m1/100} шкоди від тіні ворогам, які стоять у ній, щосекунди протягом $d.",
        [432042] = "Коли ви застосовуєте «Ланцюгове зцілення» або «Приплив», ви отримуєте $s1 зарядів «Припливних хвиль», що зменшують час вимовляння «Хвилі зцілення» на $432041s1%, «Ланцюгового зцілення» на $432041s3% і збільшують ймовірність критичного ефекту «Малої хвилі зцілення» на $432041s2%.",
        [432137] = "Назавжди зачаровує предмет у комірці наплічників, збільшуючи вашу швидкість атаки на $s1%.",
        [432139] = "Назавжди зачаровує предмет у комірці наплічників, збільшуючи вашу швидкість атаки на $432137s1%.",
        [432140] = "Ваш «Щит блискавки» більше не втрачає зарядів, тепер має $m2 с часу відновлення та завдає шкоди всім ворогам у межах $432143a1 ярдів.",
        [432190] = "Назавжди зачаровує предмет у комірці шолома, надаючи вам 20 енергії або 5 люті під час перевтілення у форму кота або ведмедя.",
        [432256] = "Ви отримуєте $432255s1 енергії щоразу, коли завдаєте критичного удару ближнього або дальнього бою.",
        [432259] = "Ви маєте $m1% шанс отримати $432260s1 енергії щоразу, коли завдаєте шкоди ближнього бою зброєю в другій руці.",
        [432273] = "Щоразу, коли ви ухиляєтеся або парируєте атаку, ви отримуєте «Нечесну перевагу», завдаючи у відповідь $432274s2% шкоди зброєю в основній руці та отримуючи $432274s3 $lpoint:points; серії. Це не може відбуватися частіше ніж раз на секунду.",
        [432276] = "Ваші здібності завдають на $432275s1% більше шкоди цілям, ураженим одним із ваших ефектів кровотечі. Ваш «Розрив» також зцілює вас на $s2% від завданої ним шкоди.",
        [433107] = "Поки ви у формі кота, ведмедя або лютого ведмедя, учасники групи в межах $407975a1 ярдів отримують підвищену бойову лютість.  Кожен удар ближнього бою має $407975h% шанс надати атакувальнику додаткову атаку з $407975s1% додаткової сили атаки. Не діє, якщо учасник групи вже отримує користь від «Тотема люті вітру».\r\n",
        [433251] = "Електрошокер 6000 випускає розряд блискавки в найдальшу ціль, завдаючи $s1 шкоди від сил природи та перескакуючи до $x разів.  Кожен гравець, уражений цим ефектом, отримує на $s2% більше шкоди від «Статичної дуги» протягом $d.",
        [433359] = "Електрошокер 6000 змінює полярність цілі, через що вона притягує гравців у межах $433363A1 ярдів кожні $s3 с і завдає $433363s1 шкоди від сил природи.",
        [433363] = "Електрошокер 6000 змінює полярність цілі, через що вона притягує гравців у межах $433363A1 ярдів кожні $s3 с і завдає $433363s1 шкоди від сил природи.",
        [433398] = "Електрошокер 6000 вивільняє імпульс електрики, завдаючи $s1 шкоди від сил природи й відкидаючи всіх гравців.",
        [433546] = "Заклинач випускає хвилю токсичного слизу в усіх гравців, завдаючи $s1 шкоди від сил природи та ще $s2 шкоди від сил природи кожні $t2 с протягом $d.  Цей ефект накопичується.",
        [433551] = "Полийте стародавній саджанець водою.",
        [433797] = "Ви атакуєте всіх ворогів поблизу протягом $d, завдаючи шкоди зброєю плюс додатково $9633s1 кожні $t1 с.",
        [433801] = "Ви атакуєте всіх ворогів поблизу протягом $d, завдаючи шкоди зброєю плюс додатково $9633s1 кожні $t1 с.",
