        [437995] = "Висмоктує ціль.",
        [437997] = "Коли ваш вихованець завдає критичного удару особливою здібністю, ви миттєво відновлюєте $437999s1% максимальної мани. Це не може відбуватися частіше ніж раз на 2 с.",
        [438040] = "Знімає всі наявні очки серії з вашої цілі та зберігає їх до $d. Ці збережені очки серії буде перенесено на наступного ворога, не керованого гравцем, якого ви вразите здібністю ближнього або дальнього бою.\r\n",
        [438062] = "Воєначальник",
        [438101] = "Пожирає гравців поблизу, завдаючи $s1 шкоди від сил природи. Також зменшує завдану ними шкоду на $s3% і швидкість руху на $s5% протягом $d.",
        [438105] = "Надає 250 честі.",
        [438130] = "Створює калюжу нудотного газу, що завдає гравцям усередині $438136s1 шкоди від сил природи та зменшує швидкість їхніх атак і вимовляння заклять на $438136s2%.",
        [438136] = "Створює калюжу нудотного газу, що завдає гравцям усередині $438136s1 шкоди від сил природи та зменшує швидкість їхніх атак і вимовляння заклять на $438136s2%.",
        [438142] = "Заклинач вкриває цілі гидотою, завдаючи $s1 шкоди від сил природи кожні $t1 с і зменшуючи швидкість їхнього руху на $s2% протягом $d.",
        [438170] = "Бальназзар занурює собор у темряву, накладаючи мовчанку на всіх гравців.",
        [438305] = "Змушує Темного вершника поблизу виявити себе.",
        [439084] = "Навчає шити багряну шовкову мантію.",
        [439090] = "Навчає шити земляний шовковий пояс.",
        [439092] = "Навчає шити багряні шовкові наплічники.",
        [439096] = "Навчає шити чоботи чарівника.",
        [439106] = "Навчає створювати велику маску вуду.",
        [439109] = "Навчає створювати велику мантію вуду.",
        [439111] = "Навчає створювати шкіряні наручі вартового.",
        [439113] = "Навчає створювати пояс вартового.",
        [439119] = "Навчає створювати рукавиці з черепашачої луски.",
        [439121] = "Навчає виготовляти рукавиці із золотої луски.",
        [439123] = "Навчає виготовляти чоботи із золотої луски.",
        [439125] = "Навчає виготовляти кірасу із золотої луски.",
        [439127] = "Навчає виготовляти каптур із золотої луски.",
        [439129] = "Навчає виготовляти місячносталевий палаш.",
        [439131] = "Навчає виготовляти наплічники із золотої луски.",
        [439133] = "Навчає виготовляти поножі із золотої луски.",
        [439431] = "Наповнює зброю шамана вітром.  Кожен удар має 20% шанс надати вам $8233s2 додаткові $lattack:attacks; з $8233s1 додаткової сили атаки ближнього бою.  Триває 5 хвилин.",
        [439462] = "Покриває зброю отрутою на 30 хвилин.\r\nКожен удар має $h% шанс отруїти ворога, зменшуючи його броню на $439471s1 протягом $439471d.\r\n\r\nСальна отрута отримує переваги від таланту «Покращене оголення броні».",
        [439464] = "Покриває зброю отрутою на 30 хвилин.\r\nКожен удар має $h% шанс отруїти ворога, збільшуючи інтервал між його атаками ближнього бою на $439472s1% протягом $439472d.",
        [439465] = "Покриває зброю отрутою на 30 хвилин.\r\nКожен удар має $h% шанс отруїти ворога, зменшуючи його силу атаки ближнього бою на $439473s1 протягом $439473d.",
        [439500] = "Покриває зброю отрутою на 30 хвилин.\r\nКожен удар має $439462h% шанс отруїти ворога, зменшуючи його броню на $439471s1 протягом $439471d.  105 зарядів.\r\n\r\nСальна отрута отримує переваги від таланту «Покращене оголення броні».",
        [439503] = "Покриває зброю отрутою на 30 хвилин.\r\nКожен удар має $439465h% шанс отруїти ворога, зменшуючи його силу атаки ближнього бою на $439473s1 протягом $439473d.  105 зарядів.",
        [439505] = "Покриває зброю отрутою на 30 хвилин.\r\nКожен удар має $439464h% шанс отруїти ворога, збільшуючи інтервал між його атаками ближнього бою на $439472s1% протягом $439472d.  105 зарядів.",
        [439733] = "Перетворює на Древо життя. У цій формі отримуване зцілення збільшується на $439745s1% для всіх учасників групи в межах $439745a1 ярдів, зцілення «Дикого зростання» збільшується на $439734s8%, ваші закляття періодичного зцілення коштують на $439734s1% менше, ви отримуєте на $439734s2% більше духу, на $439734s3% більше броні та не можете застосовувати шкідливі закляття.\r\n\r\nПеревтілення звільняє заклинача від «Поліморфії» та ефектів, що обмежують рух.",
        [439748] = "Ви прикликаєте з неба шквал зірок протягом $d, що вражають цілі в межах $439755a ярдів від вас. Кожна завдає своїй цілі від ${$439753m1*$<damagepower>/100} до ${$439753M1*$<damagepower>/100} шкоди від таємної магії та ${$439756m1*$<damagepower>/100} шкоди від таємної магії всім іншим ворогам у межах $439756a1 ярдів. Максимум 20 зірок.\r\n\r\nПеревтілення або сідання на верхового звіра скасовує ефект. Будь-який ефект, через який ви втрачаєте контроль над персонажем, призупиняє «Зорепад».\r\n\r\nОтримує переваги від більшості талантів та ефектів, що спрацьовують від «Місячного сяйва» або посилюють його.",
        [439753] = "Ви прикликаєте з неба шквал зірок на всі цілі в межах 30 ярдів від заклинача, кожна з яких завдає $50288s1 шкоди від таємної магії. Також завдає $50294s1 шкоди від таємної магії всім іншим ворогам у межах $50294a1 ярдів від ворожої цілі. Максимум 20 зірок. Триває $48505d.",
        [440212] = "Завдає $s1 шкоди від криги в радіусі 5 ярдів.",
        [440236] = "Використайте на Гіпнотичному клинку, щоб створити потужну зброю.",
        [440484] = "Коли ви завдаєте цілі шкоди «Кровожерливістю», «Смертельним ударом» або «Ударом щитом», перший раз це зі 100% ймовірністю, а кожен наступний — із $s2% ймовірністю вводить вас у стан люті (активуючи здібності, що потребують цього стану) і збільшує вашу фізичну шкоду на $440483s1% протягом $440483d.",
        [440488] = "Воїн випускає перед собою хвилю сили, завдаючи ${$m3/100*$AP} шкоди та приголомшуючи всіх ворогів у фронтальному конусі в межах $a1 ярдів на $d.",
        [440529] = "Зменшує витрати мани на ваші пастки та здібності ближнього бою на $s1%. Крім того, ваші критичні удари мають $m3% шанс дозволити $1242688s1% відновлення мани продовжуватися під час вимовляння заклять протягом $1242688d.",
        [440533] = "Після використання «Удару раптора» ваша швидкість руху збільшується на $440531s1% протягом $440531d.\r\n\r\nЗдібності вашого вихованця, що завдають шкоди, вводять ціль у скажене шаленство, збільшуючи її силу атаки ближнього бою на $s2, але зменшуючи броню на $s3 протягом $1218358d.  Скажені вороги не тікають і ігнорують ефекти страху та жаху.",
        [440569] = "Зменшує час відновлення «Ланцюгової блискавки» на $s1%, змушує «Тотем оковування землі» при застосуванні вкорінювати цілі на $440574d і збільшує періодичну шкоду «Вогняного шоку» на $s3%.",
        [440580] = "Прикликає двох примарних вовків під командування шамана на $d.",
        [440589] = "Ваші примарні вовки виють, змушуючи всіх ворогів атакувати їх протягом $d.",
        [440591] = "Знімає всі ефекти, що обмежують рух, і збільшує швидкість руху вас та ваших примарних вовків на $s1% протягом $d.",
        [440610] = "Знімає всі ефекти, що обмежують рух.",
        [440651] = "Щоразу, коли ціль отримує шкоду, вона здобуває «Священний щит», що поглинає $s1 шкоди та збільшує ймовірність критичного ефекту «Спалаху Світла» паладина на $s2% на час до $d.  Цей ефект не може виникати частіше ніж раз на 6 с.  Триває $d.\r\n",
        [440666] = "Коли спрацьовує ваш талант «Виправдання», він також зменшує силу атаки цілі на ${$440667m1/-3} за кожне очко таланту та збільшує вашу силу, спритність і силу атаки на ${$440668m1/3}% за кожне очко таланту. Тривалість «Виправдання» збільшено до $s1 с.",
        [440672] = "Коли ваше «Правосуддя» або «Удар хрестоносця» завдає критичного удару, ціль отримує додатково $s1% шкоди протягом $61840d.",
        [440802] = "Запускає сферу закрученої криги, що швидко рухається вперед протягом $d. Під час руху кожні $440804t с сфера завдає ${$440809m2*$<power>/100*$<frostdamage>} шкоди від криги та накладає «Охолодження», зменшуючи швидкість руху всіх ворогів, крізь яких проходить, на $440809s1%. Після першого завдання шкоди ворогові її рух сповільнюється, і вона зі 100% ймовірністю активує руну «Пальці криги».",
        [440820] = "..",
        [440827] = "Киньте в киплячий казан, щоб спричинити вибух шкідливого газу. Не порушує непомітність.",
        [440829] = "Поєднайте підношення плоті й кісток.",
        [440830] = "Наповніть порожнисту емблему сутністю магії крові.",
        [440841] = "Виявляє могилу, в якій заховано підношення.",
        [440870] = "Зменшує час відновлення вашого «Вогню душі» на $m2%. Коли ви застосовуєте «Тіньову стрілу» або «Пекучий біль» до ворога з менш ніж $m3% здоров’я, вони завдають на $m4% більше шкоди, а протягом наступних $440873d час вимовляння «Вогню душі» зменшується на $m1% і він не витрачає уламків душі.",
        [440882] = "Ваш дух наповнюється демонічною енергією, зменшуючи всю отримувану магічну шкоду на величину, що дорівнює $s2% вашого зменшення фізичної шкоди від броні. Триває $d.",
        [440892] = "Проклинає ціль на $d, зменшуючи її опори магії на $s1 і збільшуючи отримувану магічну шкоду на $s2%. На одній цілі від одного чорнокнижника може діяти лише одне прокляття.",
        [442211] = "Після активації ваша здібність «Калічення (ведмідь)» уражає до $s3 цілей і більше не має часу відновлення, а витрати енергії на всі здібності у формі кота зменшуються на $s1%.  Триває $d. Для активації потрібна форма ведмедя, кота або лютого ведмедя.\r\n\r\nЗнімає страх і надає несприйнятливість до страху на час дії.\r\n",
        [442222] = "Електрошокер 6000 випускає розряд блискавки в найдальшу ціль, завдаючи $s1 шкоди від сил природи та перескакуючи до $x разів.  Кожен гравець, уражений цим ефектом, отримує на $s2% більше шкоди від «Статичної дуги» протягом $d.",
        [442223] = "Електрошокер 6000 випускає розряд блискавки в найдальшу ціль, завдаючи $s1 шкоди від сил природи та перескакуючи до $x разів.  Кожен гравець, уражений цим ефектом, отримує на $s2% більше шкоди від «Статичної дуги» протягом $d.",
        [442225] = "Електрошокер 6000 випускає розряд блискавки в найдальшу ціль, завдаючи $s1 шкоди від сил природи та перескакуючи до $x разів.  Кожен гравець, уражений цим ефектом, отримує на $s2% більше шкоди від «Статичної дуги» протягом $d.",
        [442893] = "Ймовірність влучання закляттями збільшено на $s1%. Не сумується з іншими рунами перснів.",
        [442894] = "Ймовірність влучання закляттями збільшено на $s1%. Не сумується з іншими рунами перснів.",
        [442895] = "Ймовірність влучання закляттями збільшено на $s1%. Не сумується з іншими рунами перснів.",
        [442896] = "Ймовірність влучання закляттями збільшено на $s1%. Не сумується з іншими рунами перснів.",
        [442897] = "Ймовірність влучання закляттями збільшено на $s1%. Не сумується з іншими рунами перснів.",
        [442898] = "Ймовірність влучання закляттями збільшено на $s1%. Не сумується з іншими рунами перснів.",
        [442901] = "У формі ведмедя, кота або лютого ведмедя ймовірність влучання атаками ближнього бою збільшено на $s2%, а ймовірність ухилення ворогів від ваших атак ближнього бою зменшено на $s1%. Не сумується з іншими рунами перснів.",
        [442948] = "Вибраного учасника групи захищено від усіх фізичних атак на $d, але протягом цього часу він не може атакувати або використовувати фізичні здібності.  На гравцеві одночасно може діяти лише одне благословення від кожного паладина.  Після захисту ціль не може знову стати невразливою від «Божественного щита», «Божественного захисту» або «Благословення захисту» протягом $25771d.",
        [443265] = "Завдає $o1 шкоди від вогню протягом $d. Демони та звірі вкорінюються на місці на $1312052d.",
        [443358] = "Атакує до $i ворогів у межах $a1 ярдів, завдаючи кожному шкоди зброєю, і скидає час відновлення «Вихору».",
        [443630] = "Знімає всі ефекти, що обмежують рух, і всі ефекти, через які ви втрачаєте контроль над персонажем.",
        [443631] = "Вирощує з трупа гуманоїда або звіра «Цілющий цвіт» на $d, який зцілює учасників групи в межах $443464a1 ярдів на $443464s1 кожні $443464t1 с.",
        [443632] = "Збільшує ваш ефективний рівень непомітності на 3. Збільшує дальність «Знешкодження пастки» та «Кишенькової крадіжки» на $s2 ярдів, а «Відволікання» — на $s3 ярдів.",
        [443917] = "Кров наповнює заклинача, відновлюючи $s1% максимальної мани кожні $t1 с.",
        [443975] = "Завдає $s1 шкоди від тіні кожні $t1 с протягом $d.\r\nШвидкість атак, вимовляння заклять і руху зменшена на $s2% на час дії.",
        [443990] = "Видає жахливе виття, завдаючи $s1 шкоди від тіні всім ворогам і змушуючи їх тікати в страху протягом $d.",
        [444046] = "Змушує ворогів поблизу говорити демонічною мовою, зменшуючи швидкість вимовляння їхніх заклять на $s1% протягом $d. ",
        [444050] = "Обливає гравців кров’ю, завдаючи $s1 шкоди від тіні.",
        [444165] = "Висмоктує з цілі плоть і кров, перетворюючи її на скелет на $d. Під дією ефекту ціль отримує на $s1% менше зцілення та рухається на $2% швидше.",
        [444253] = "Плює оскверненою кров’ю, завдаючи $444261s1 шкоди від тіні кожні $444255t1 с. Ефект може поширитися на гравців поблизу.",
        [444255] = "Плює оскверненою кров’ю, завдаючи $444261s1 шкоди від тіні кожні $444255t1 с. Ефект може поширитися на гравців поблизу.",
        [444261] = "Плює оскверненою кров’ю, завдаючи $444261s1 шкоди від тіні кожні $444255t1 с. Ефект може поширитися на гравців поблизу.",
        [444273] = "Плює оскверненою кров’ю, завдаючи $444284s1 шкоди від тіні кожні $t1 с. Ефект може поширитися на гравців поблизу.",
        [444280] = "Плює оскверненою кров’ю, завдаючи $444261s1 шкоди від тіні кожні $444255t1 с. Ефект може поширитися на гравців поблизу.",
