        [457440] = "«Зникнення» тепер зменшує всю отримувану магічну шкоду на $457437s1% на час дії, але більше не надає непомітності й не знімає ефекти, що обмежують рух.",
        [457464] = "Ваші завершальні прийоми мають $b1% шанс за кожне очко серії зменшити на $457469s1% фізичну шкоду від наступної атаки ближнього бою, що влучить у вас протягом $457469d.",
        [457520] = "Критичні удари «Блискавки» мають $h% шанс скинути час відновлення «Виверження лави» та «Ланцюгової блискавки» й зробити наступне «Виверження лави» або «Ланцюгову блискавку» протягом $415105d миттєвим.\r\n",
