        [457614] = "Вивільняє силу ударом ноги, відкидаючи та завдаючи шкоди ворогам поблизу.",
        [457642] = "Удари «Тіньового розсічення» мають $h% шанс надати уламок душі, скинути час відновлення «Вогню душі» та зробити ваш наступний «Вогонь душі» протягом $457643d миттєвим.",
        [457697] = "Протягом $457699d після виходу зі стійки ви можете використовувати здібності, що потребують цієї стійки, ніби все ще перебуваєте в ній.",
        [457820] = "Протягом перших $457816d після активації стійки ви отримуєте додаткову перевагу:\r\n\r\nБойова стійка/Стійка гладіатора: $457816s1% додаткової шкоди.\r\n\r\nСтійка берсерка: $457817s1% додаткової ймовірності критичного удару.\r\n\r\nЗахисна стійка: $457814s1% менше отримуваної фізичної шкоди.",
        [457847] = "Згори падають зорі, завдаючи $s1 шкоди.",
        [458312] = "Зменшує всю отримувану шкоду на $s1% протягом $d.  Після захисту ви не можете знову стати ціллю «Божественного щита», «Божественного захисту» або «Благословення захисту» протягом $25771d.",
        [458318] = "Тепер ви можете діяти під час «Божественного захисту», а його тривалість збільшена на $s3%, але замість несприйнятливості він лише зменшує отримувану шкоду на $458312s1%. Крім того, активація «Святого щита» також надає вам $460171s2 сили атаки за кожне очко навички захисту понад ${$PL*5}, на $460171d.",
        [458371] = "Зменшує всю отримувану шкоду на $s1% протягом $d.  Після захисту ви не можете знову стати ціллю «Божественного щита», «Божественного захисту» або «Благословення захисту» протягом $25771d.",
        [458436] = "Лютий удар, що завдає $s2% шкоди зброєю та спричиняє кровотечу на ${$m3/100*8*$AP} фізичної шкоди протягом $d.",
        [458454] = "Піднесіть відлуння.",
        [458479] = "Замінює вашу здібність «Жало виверни» на «Удар виверни» — лютий удар, що завдає $458436s2% шкоди зброєю та спричиняє періодичну кровотечу.\r\n\r\n«Удар виверни» потребує таланту «Жало виверни» та замінює здібності «Жало виверни» в книзі заклять «Виживання».",
        [458481] = "Лютий удар, що завдає $s2% шкоди зброєю та спричиняє кровотечу на ${$m3/100*8*$AP} фізичної шкоди протягом $d.",
        [458482] = "Лютий удар, що завдає $s2% шкоди зброєю та спричиняє кровотечу на ${$m3/100*8*$AP} фізичної шкоди протягом $d.",
        [458821] = "Покриває зброю отрутою на 30 хвилин. Кожен удар має $h% шанс отруїти ворога на $458820o1 шкоди від сил природи протягом $458820d і збільшити отримувану ним шкоду від таємної магії, вогню, криги, сил природи й тіні на $458820s2%.  Ефект накопичується до $458820u разів на одній цілі.\r\n\r\n«Окультна отрута» вважається «Смертельною отрутою» й отримує переваги від усіх талантів та ефектів, що спрацьовують від «Смертельної отрути» або змінюють її.\r\n",
        [458822] = "Покриває зброю отрутою на 30 хвилин.\r\nКожен удар має 30% шанс отруїти ворога на $458820o1 шкоди від сил природи протягом $458820d і збільшити отримувану ним шкоду від таємної магії, вогню, криги, сил природи й тіні на $458820s2%.  Ефект накопичується до $458820u разів на одній цілі.\r\n\r\n«Окультна отрута» вважається «Смертельною отрутою» й отримує переваги від усіх талантів та ефектів, що спрацьовують від «Смертельної отрути» або змінюють її.",
        [458856] = "Зцілює дружню ціль на від ${$<healpower>*$m1/100} до ${$<healpower>*$M1/100}. $s2% надлишкового зцілення цілі перетворюється на щит поглинання, що триває $458857d. Кілька застосувань «Божественного Світла» не накопичують цей щит.\r\n\r\n«Божественне Світло» отримує переваги від усіх талантів та ефектів, що спрацьовують від «Святого Світла» або змінюють його.",
